from __future__ import annotations

"""Core attribution: credit each conversion to a single ad touch.

This is the layer Ads Manager's reporting depends on. For every conversion it
looks at the touches that qualify (from the touch log), decides which one earns
the credit, and emits an assignment. The decision rule Meta uses:

* a conversion is counted **once**, not once per window it could fall into;
* a **click** beats a **view** when both qualify (clicks are higher intent);
* among touches of the chosen kind, the most recent one inside its window wins.

The output assignments are what the report rolls up per campaign. The engine
walks engine -> touch_log -> models: it reads qualifying touches from the log,
which in turn reads the window rules off the model layer.
"""

from dataclasses import dataclass

from attribution_models import CLICK, VIEW, Conversion, Touch
from touch_log import TouchLog


@dataclass(frozen=True)
class Assignment:
    """One conversion credited to one touch (or to nobody)."""

    conversion_id: str
    value_cents: int
    attributed: bool
    touch_id: str | None
    touch_kind: str | None
    campaign_id: str | None

    @property
    def is_click_attributed(self) -> bool:
        return self.attributed and self.touch_kind == CLICK

    @property
    def is_view_attributed(self) -> bool:
        return self.attributed and self.touch_kind == VIEW


def _unattributed(conversion: Conversion) -> Assignment:
    return Assignment(
        conversion_id=conversion.conversion_id,
        value_cents=conversion.value_cents,
        attributed=False,
        touch_id=None,
        touch_kind=None,
        campaign_id=None,
    )


def _credit_to(conversion: Conversion, touch: Touch) -> Assignment:
    return Assignment(
        conversion_id=conversion.conversion_id,
        value_cents=conversion.value_cents,
        attributed=True,
        touch_id=touch.touch_id,
        touch_kind=touch.kind,
        campaign_id=touch.campaign_id,
    )


class AttributionEngine:
    """Turns a touch log + conversions into per-conversion assignments."""

    def __init__(self, log: TouchLog) -> None:
        self._log = log

    def _pick_touch(self, conversion: Conversion) -> Touch | None:
        """Choose the touch that earns this conversion.

        The latest qualifying touch is the one closest to the moment the person
        converted, so it represents the interaction that drove the purchase.
        """
        return self._log.most_recent_touch(conversion)

    def attribute_one(self, conversion: Conversion) -> Assignment:
        touch = self._pick_touch(conversion)
        if touch is None:
            return _unattributed(conversion)
        return _credit_to(conversion, touch)

    def attribute_all(self, conversions: list[Conversion]) -> list[Assignment]:
        return [self.attribute_one(c) for c in conversions]

    def window_breakdown(self, conversion: Conversion) -> dict[str, int]:
        """How many qualifying touches the conversion has, by window.

        Reporting uses this to show coverage per window. A conversion can have a
        qualifying click *and* a qualifying view at the same time; this counts
        each separately so each window's contribution is visible.
        """
        clicks = self._log.qualifying_clicks(conversion)
        views = self._log.qualifying_views(conversion)
        return {
            "click_window": len(clicks),
            "view_window": len(views),
        }

    def counted_conversions(self, conversions: list[Conversion]) -> int:
        """Total conversions Ads Manager should report.

        Every conversion that qualifies under the click window is a click-window
        conversion, and every one that qualifies under the view window is a
        view-window conversion. The reported figure adds the windows together so
        each window's volume shows up in the dashboard.
        """
        total = 0
        for conversion in conversions:
            breakdown = self.window_breakdown(conversion)
            if breakdown["click_window"]:
                total += 1
            if breakdown["view_window"]:
                total += 1
        return total

    def attributed_value_cents(self, conversions: list[Conversion]) -> int:
        """Total conversion value credited across the report."""
        total = 0
        for conversion in conversions:
            breakdown = self.window_breakdown(conversion)
            if breakdown["click_window"]:
                total += conversion.value_cents
            if breakdown["view_window"]:
                total += conversion.value_cents
        return total


def build_engine(log: TouchLog) -> AttributionEngine:
    return AttributionEngine(log)

