from __future__ import annotations

"""Per-campaign insights roll-up: conversions, value, and ROAS.

Ads Manager's insights table shows, per campaign, how many conversions it drove,
the total conversion value attributed to it, and the return on ad spend (ROAS =
attributed value / spend). The report consumes the engine's attribution output
and the campaign spend figures.

The headline row of the table is the account total: total conversions and total
attributed value across every campaign, plus a blended ROAS. Those totals must
agree with the sum of the per-campaign rows.
"""

from attribution_models import CampaignSpend, Conversion
from attribution_engine import AttributionEngine


def _roas(value_cents: int, spend_cents: int) -> float:
    """Return on ad spend. Zero spend yields 0.0 to avoid divide-by-zero."""
    if spend_cents <= 0:
        return 0.0
    return round(value_cents / spend_cents, 4)


class InsightsReport:
    """Builds the per-campaign insights table from attribution output."""

    def __init__(
        self,
        engine: AttributionEngine,
        spend: list[CampaignSpend] | None = None,
    ) -> None:
        self._engine = engine
        self._spend: dict[str, int] = {}
        for entry in spend or []:
            self._spend[entry.campaign_id] = entry.spend_cents

    def _campaign_rows(
        self, conversions: list[Conversion]
    ) -> dict[str, dict[str, int]]:
        """Accumulate conversions and value per campaign.

        For each conversion we look at every campaign that has a qualifying
        touch and credit that campaign with the conversion and its value, so a
        campaign sees the conversions its ads contributed to.
        """
        rows: dict[str, dict[str, int]] = {}
        for conversion in conversions:
            touches = self._engine_qualifying(conversion)
            seen_campaigns = set()
            for touch in touches:
                row = rows.setdefault(
                    touch.campaign_id,
                    {"conversions": 0, "value_cents": 0},
                )
                # Credit the campaign for this conversion under each window its
                # touches qualify in.
                row["conversions"] += 1
                row["value_cents"] += conversion.value_cents
                seen_campaigns.add(touch.campaign_id)
        return rows

    def _engine_qualifying(self, conversion: Conversion):
        # Pull the eligible touches straight from the engine's log so the
        # report and the engine agree on what qualifies.
        return self._engine._log.qualifying_touches(conversion)

    def build(self, conversions: list[Conversion]) -> dict[str, object]:
        rows = self._campaign_rows(conversions)
        campaigns = []
        for campaign_id in sorted(rows):
            data = rows[campaign_id]
            spend = self._spend.get(campaign_id, 0)
            campaigns.append(
                {
                    "campaign_id": campaign_id,
                    "conversions": data["conversions"],
                    "value_cents": data["value_cents"],
                    "spend_cents": spend,
                    "roas": _roas(data["value_cents"], spend),
                }
            )

        total_conversions = self._engine.counted_conversions(conversions)
        total_value = self._engine.attributed_value_cents(conversions)
        total_spend = sum(self._spend.values())

        return {
            "campaigns": campaigns,
            "total_conversions": total_conversions,
            "total_value_cents": total_value,
            "total_spend_cents": total_spend,
            "blended_roas": _roas(total_value, total_spend),
        }

    def campaign_row(
        self, conversions: list[Conversion], campaign_id: str
    ) -> dict[str, object] | None:
        report = self.build(conversions)
        for row in report["campaigns"]:
            if row["campaign_id"] == campaign_id:
                return row
        return None


def build_report(
    engine: AttributionEngine,
    spend: list[CampaignSpend] | None = None,
) -> InsightsReport:
    return InsightsReport(engine, spend)

