from __future__ import annotations

"""Per-user ordered log of ad touches.

Attribution is always scoped to one person: a click or a view can only claim a
conversion made by the same ``user_id``. This module keeps each user's touches
in timestamp order and answers the question the engine asks over and over:
"which touches happened before this conversion and are still inside their
attribution window?"

A touch qualifies for a conversion when it happened *before* the conversion and
the gap from the touch to the conversion falls inside the touch's window. Clicks
use the 7-day window, views the 1-day window.
"""

from attribution_models import (
    CLICK_WINDOW_SECONDS,
    VIEW_WINDOW_SECONDS,
    Conversion,
    Touch,
)


class TouchLog:
    """Holds every touch, grouped and ordered by user."""

    def __init__(self) -> None:
        self._by_user: dict[str, list[Touch]] = {}

    def add(self, touch: Touch) -> None:
        bucket = self._by_user.setdefault(touch.user_id, [])
        bucket.append(touch)
        # Keep the per-user log sorted by time so window scans are linear.
        bucket.sort(key=lambda t: t.ts)

    def extend(self, touches: list[Touch]) -> None:
        for touch in touches:
            self.add(touch)

    def touches_for_user(self, user_id: str) -> list[Touch]:
        return list(self._by_user.get(user_id, []))

    def user_ids(self) -> list[str]:
        return list(self._by_user.keys())

    def _within_window(self, touch: Touch, conversion: Conversion) -> bool:
        """True when ``touch`` is eligible to claim ``conversion``.

        The touch must precede the conversion, and the elapsed time from touch
        to conversion must land inside the touch's attribution window. Clicks
        get the longer 7-day window, views the 1-day window.
        """
        if touch.ts > conversion.ts:
            return False
        gap = conversion.ts - touch.ts
        if touch.is_click:
            return gap <= CLICK_WINDOW_SECONDS
        return gap <= VIEW_WINDOW_SECONDS

    def qualifying_touches(
        self, conversion: Conversion
    ) -> list[Touch]:
        """All touches for the conversion's user that are inside their window.

        Returned in timestamp order (oldest first). The engine decides which one
        of these actually earns the credit; the log just narrows the field to
        the eligible touches.
        """
        candidates = self._by_user.get(conversion.user_id, [])
        eligible = [
            touch
            for touch in candidates
            if self._within_window(touch, conversion)
        ]
        eligible.sort(key=lambda t: t.ts)
        return eligible

    def qualifying_clicks(self, conversion: Conversion) -> list[Touch]:
        return [t for t in self.qualifying_touches(conversion) if t.is_click]

    def qualifying_views(self, conversion: Conversion) -> list[Touch]:
        return [t for t in self.qualifying_touches(conversion) if t.is_view]

    def most_recent_touch(self, conversion: Conversion) -> Touch | None:
        """Return the latest-by-time qualifying touch, if any.

        Ties on timestamp resolve to the touch that was appended later, which
        matches the order Ads Manager streams events in.
        """
        eligible = self.qualifying_touches(conversion)
        if not eligible:
            return None
        latest = eligible[0]
        for touch in eligible[1:]:
            if touch.ts >= latest.ts:
                latest = touch
        return latest

    def has_any_touch(self, conversion: Conversion) -> bool:
        return bool(self.qualifying_touches(conversion))


def build_log(touches: list[Touch]) -> TouchLog:
    log = TouchLog()
    log.extend(touches)
    return log

